        public static GameObject CreateCharacter(string name, string color, float scale, bool hero = false)
        {
            var root = new GameObject(name);
            var view = root.AddComponent<StylizedActorView>();
            var body = new GameObject("Animated body").transform;
            body.SetParent(root.transform, false);
            view.body = body;
            var torso = Part(body, "Coat", new Vector3(0f, 1.22f, 0f),
                new Vector3(0.9f, 0.82f, 0.7f), "Body", color);
            view.coat = torso.GetComponent<Renderer>();
            Part(body, "Belt", new Vector3(0f, 0.93f, 0f), new Vector3(0.75f, 0.13f, 0.57f), "Box", "Ink");
            Part(body, "Buckle", new Vector3(0f, 0.95f, 0.32f), new Vector3(0.17f, 0.17f, 0.08f), "Box", "Gold");
            Part(body, "Face", new Vector3(0f, 1.92f, 0.02f), new Vector3(0.55f, 0.59f, 0.52f),
                "Rock", hero ? "Skin" : "StoneDark");
            Part(body, "Helmet", new Vector3(0f, 2.10f, -0.02f),
                new Vector3(0.68f, 0.43f, 0.64f), "Body", hero ? "StoneLight" : color);
            Part(body, "Helmet crest", new Vector3(0f, 2.38f, -0.06f),
                new Vector3(0.14f, 0.36f, 0.52f), "Blade", hero ? "Teal" : "Gold");
            for (var side = -1; side <= 1; side += 2)
            {
                Part(body, "Eye", new Vector3(side * 0.14f, 1.96f, 0.26f),
                    new Vector3(0.10f, 0.08f, 0.05f), "Box", hero ? "Ink" : "Glow");
                Part(body, "Shoulder guard", new Vector3(side * 0.49f, 1.58f, 0f),
