            }

            view.leftLeg = Limb(body, "Left leg", new Vector3(-0.22f, 0.75f, 0f), "Ink");
            view.rightLeg = Limb(body, "Right leg", new Vector3(0.22f, 0.75f, 0f), "Ink");
            Limb(body, "Left arm", new Vector3(-0.53f, 1.50f, 0f), color);
            view.weaponArm = Limb(body, "Weapon arm", new Vector3(0.53f, 1.50f, 0f), color);
