            Part(view.weaponArm, "Axe binding", new Vector3(0f, -0.07f, 0.40f),
                new Vector3(0.15f, 0.16f, 0.15f), "Box", "Gold");
            Part(body, "Chest plate", new Vector3(0f, 1.36f, 0.31f),
                new Vector3(0.53f, 0.45f, 0.13f), "Body", hero ? "StoneLight" : "StoneDark");
            Part(body, "Chest rune", new Vector3(0f, 1.40f, 0.39f),
                new Vector3(0.15f, 0.23f, 0.07f), "Rock", hero ? "Gold" : "Glow");
            Part(body, "Travel cloak", new Vector3(0f, 1.19f, -0.34f),
                new Vector3(0.78f, 0.93f, 0.13f), "Body", hero ? "Teal" : "Ink");
