        private static void Tree(Transform parent, Vector3 position, float scale, int variant)
        {
            var tree = new GameObject("Mosswatch pine").transform;
            tree.SetParent(parent, false);
            tree.localPosition = position;
            tree.localScale = Vector3.one * scale;
            Part(tree, "Trunk", Vector3.up * 1.1f, new Vector3(0.32f, 2.2f, 0.32f), "Pillar", "Bark");
            for (var tier = 0; tier < 3; tier++)
            {
                var canopy = Part(tree, "Faceted canopy", Vector3.up * (1.9f + tier * 0.8f),
                    new Vector3(2.9f - tier * 0.6f, 1.9f, 2.9f - tier * 0.6f), "Cone",
                    tier == 2 ? "LeafLight" : variant % 3 == 0 ? "Pine" : "Leaf");
                canopy.transform.localRotation = Quaternion.Euler(0f, variant * 17f + tier * 23f, 0f);
            }
        }

        private static void Lantern(Transform root, Vector3 position)
        {
            Part(root, "Way lantern pedestal", position + Vector3.up * 0.45f,
                new Vector3(0.2f, 0.9f, 0.2f), "Pillar", "Bark");
            Part(root, "Lantern housing", position + Vector3.up,
                new Vector3(0.42f, 0.48f, 0.42f), "Pillar", "Gold");
            Part(root, "Lantern flame", position + Vector3.up * 1.06f,
                new Vector3(0.21f, 0.35f, 0.21f), "Rock", "Glow");
        }

        private static void Ruins(Transform root, Vector3 position)
        {
            for (var i = 0; i < 3; i++)
            {
                var height = i == 1 ? 2.4f : 1.7f;
                Part(root, "Weathered column", position + new Vector3(i * 1.6f, height * 0.5f, 0f),
                    new Vector3(0.85f, height, 0.85f), "Pillar", "Stone");
                Part(root, "Column cap", position + new Vector3(i * 1.6f, height, 0f),
                    new Vector3(1f, 0.2f, 1f), "Box", "StoneLight");
            }
            Part(root, "Fallen lintel", position + new Vector3(0.8f, 0.25f, -1.2f),
                new Vector3(3f, 0.4f, 0.8f), "Box", "StoneDark");
        }

        private static void GateArch(Transform root, Vector3 position)
        {
            var arch = new GameObject("Eastern gateway").transform;
            arch.SetParent(root, false);
            arch.position = position;
            arch.rotation = Quaternion.Euler(0f, 90f, 0f);
            root = arch;
            position = Vector3.zero;
            for (var side = -1; side <= 1; side += 2)
            {
                Part(root, "Ancient gate column", position + new Vector3(side * 2.2f, 1.8f, 0f),
                    new Vector3(1f, 3.6f, 1.1f), "Pillar", "Stone");
                Part(root, "Gate crown", position + new Vector3(side * 2.2f, 3.7f, 0f),
                    new Vector3(1.2f, 0.4f, 1.3f), "Box", "StoneLight");
            }
            Part(root, "Gate lintel", position + Vector3.up * 3.8f,
                new Vector3(5.1f, 0.6f, 1.1f), "Box", "StoneDark");
            Part(root, "Gate crest", position + new Vector3(0f, 4f, -0.6f),
                new Vector3(0.5f, 0.8f, 0.15f), "Rock", "Gold");
        }

        private static Transform Limb(Transform root, string name, Vector3 position, string material)
        {
            var limb = new GameObject(name).transform;
            limb.SetParent(root, false);
            limb.localPosition = position;
            Part(limb, "Limb", new Vector3(0f, -0.25f, 0f),
                new Vector3(0.28f, 0.55f, 0.31f), "Body", material);
            Part(limb, "Boot or glove", new Vector3(0f, -0.51f, 0.07f),
                new Vector3(0.32f, 0.23f, 0.47f), "Box", "Bark");
            return limb;
        }

        private static void Boundary(Transform root, string name, Vector3 position, Vector3 size)
        {
            var item = new GameObject(name + " walk boundary", typeof(BoxCollider));
            item.transform.SetParent(root, false);
            item.transform.position = position;
            item.GetComponent<BoxCollider>().size = size;
        }

        private static void Boulder(Transform root, Vector3 position, Vector3 scale, string color, System.Random random)
        {
            var item = Part(root, "Cliff boulder", position, scale, "Rock", color);
            item.transform.rotation = Quaternion.Euler(random.Next(-15, 15), random.Next(360), random.Next(-15, 15));
        }

        private static TextMesh Label(Transform root, string name, string text, Vector3 position, float size, string color)
        {
            var item = new GameObject(name, typeof(TextMesh), typeof(WorldLabel));
            item.transform.SetParent(root, false);
            item.transform.localPosition = position;
            var label = item.GetComponent<TextMesh>();
            label.text = text;
            label.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
            label.fontSize = 64;
            label.characterSize = size;
            label.anchor = TextAnchor.MiddleCenter;
            label.color = Materials[color].color;
            label.GetComponent<Renderer>().sharedMaterial = label.font.material;
            return label;
        }

        private static GameObject Part(Transform parent, string name, Vector3 position, Vector3 scale, string mesh, string material)
        {
            var item = new GameObject(name, typeof(MeshFilter), typeof(MeshRenderer));
            item.transform.SetParent(parent, false);
            item.transform.localPosition = position;
            item.transform.localScale = scale;
            item.GetComponent<MeshFilter>().sharedMesh = Meshes[mesh];
            item.GetComponent<MeshRenderer>().sharedMaterial = Materials[material];
            return item;
        }

        private static void Palette(string name, Color color)
        {
            var path = Root + "/Materials/" + name + ".mat";
            var asset = AssetDatabase.LoadAssetAtPath<Material>(path);
            if (asset == null)
            {
                var shader = Shader.Find("Universal Render Pipeline/Lit");
                if (shader == null) throw new InvalidOperationException("URP/Lit is required for section art.");
                asset = new Material(shader);
                AssetDatabase.CreateAsset(asset, path);
            }
            asset.color = color;
            asset.SetFloat("_Smoothness", 0.12f);
            asset.enableInstancing = true;
            Materials.Add(name, asset);
            EditorUtility.SetDirty(asset);
        }

        private static void Folder(string parent, string name)
        {
            if (!AssetDatabase.IsValidFolder(parent + "/" + name)) AssetDatabase.CreateFolder(parent, name);
        }

        private static void SaveMesh(string name, Mesh generated)
        {
            var path = Root + "/Meshes/" + name + ".asset";
            var asset = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (asset == null)
            {
                asset = generated;
                AssetDatabase.CreateAsset(asset, path);
            }
            else
            {
                asset.Clear();
                asset.vertices = generated.vertices;
                asset.triangles = generated.triangles;
                asset.RecalculateNormals();
                asset.RecalculateBounds();
                Object.DestroyImmediate(generated);
                EditorUtility.SetDirty(asset);
            }
            Meshes.Add(name, asset);
        }

        private static Mesh FlatMesh(string name, List<Vector3> corners)
        {
            var indices = new int[corners.Count];
            for (var i = 0; i < indices.Length; i++) indices[i] = i;
            var mesh = new Mesh { name = name };
            mesh.SetVertices(corners);
            mesh.triangles = indices;
            mesh.RecalculateNormals();
            mesh.RecalculateBounds();
            return mesh;
        }

        private static void Triangle(List<Vector3> vertices, Vector3 a, Vector3 b, Vector3 c)
        {
            vertices.Add(a); vertices.Add(b); vertices.Add(c);
        }

        private static Mesh Frustum(int sides, float bottom, float top)
        {
            var vertices = new List<Vector3>();
            for (var i = 0; i < sides; i++)
            {
                var a = i * Mathf.PI * 2f / sides;
                var b = (i + 1) * Mathf.PI * 2f / sides;
                var p = new Vector3(Mathf.Cos(a) * bottom, -0.5f, Mathf.Sin(a) * bottom);
                var q = new Vector3(Mathf.Cos(b) * bottom, -0.5f, Mathf.Sin(b) * bottom);
                var r = new Vector3(Mathf.Cos(a) * top, 0.5f, Mathf.Sin(a) * top);
                var s = new Vector3(Mathf.Cos(b) * top, 0.5f, Mathf.Sin(b) * top);
                Triangle(vertices, p, r, s); Triangle(vertices, p, s, q);
                Triangle(vertices, Vector3.up * 0.5f, s, r);
                Triangle(vertices, Vector3.down * 0.5f, p, q);
            }
            return FlatMesh("Faceted frustum", vertices);
        }

        private static Mesh RingMesh(int sides, float inner)
        {
            var vertices = new List<Vector3>();
            for (var i = 0; i < sides; i++)
            {
                var a = new Vector3(Mathf.Cos(i * Mathf.PI * 2f / sides), 0f, Mathf.Sin(i * Mathf.PI * 2f / sides));
                var b = new Vector3(Mathf.Cos((i + 1) * Mathf.PI * 2f / sides), 0f, Mathf.Sin((i + 1) * Mathf.PI * 2f / sides));
                Triangle(vertices, a, a * inner, b);
                Triangle(vertices, b, a * inner, b * inner);
            }
            return FlatMesh("Ground ring", vertices);
        }

        private static Mesh RockMesh()
        {
            var vertices = new List<Vector3>();
            var top = Vector3.up * 0.6f;
            var bottom = Vector3.down * 0.5f;
            for (var i = 0; i < 7; i++)
            {
                var a = i * Mathf.PI * 2f / 7f;
                var b = (i + 1) * Mathf.PI * 2f / 7f;
                var p = new Vector3(Mathf.Cos(a) * 0.55f, i % 2 * 0.1f, Mathf.Sin(a) * 0.55f);
                var q = new Vector3(Mathf.Cos(b) * 0.55f, (i + 1) % 2 * 0.1f, Mathf.Sin(b) * 0.55f);
                Triangle(vertices, top, q, p);
                Triangle(vertices, bottom, p, q);
            }
            return FlatMesh("Hand-shaped crystal rock", vertices);
        }

        private static Mesh BladeMesh()
        {
            var vertices = new List<Vector3>();
            var points = new[] { new Vector2(-0.5f, -0.45f), new Vector2(0.15f, -0.3f),
                new Vector2(0.5f, 0.1f), new Vector2(0.15f, 0.5f), new Vector2(-0.5f, 0.35f) };
            for (var i = 0; i < points.Length; i++)
            {
                var j = (i + 1) % points.Length;
                var p = new Vector3(points[i].x, points[i].y, -0.5f);
                var q = new Vector3(points[j].x, points[j].y, -0.5f);
                Triangle(vertices, p, q, new Vector3(q.x, q.y, 0.5f));
                Triangle(vertices, p, new Vector3(q.x, q.y, 0.5f), new Vector3(p.x, p.y, 0.5f));
                Triangle(vertices, new Vector3(0f, 0f, -0.5f), q, p);
                Triangle(vertices, new Vector3(0f, 0f, 0.5f), new Vector3(p.x, p.y, 0.5f), new Vector3(q.x, q.y, 0.5f));
            }
            return FlatMesh("Forged axe profile", vertices);
        }
    }
}
